import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"Configuración general","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. Sistema","slug":"_1-sistema","link":"#_1-sistema","children":[]},{"level":2,"title":"2. Ventana de búsqueda rápida","slug":"_2-ventana-de-busqueda-rapida","link":"#_2-ventana-de-busqueda-rapida","children":[{"level":3,"title":"Diseño de la barra de búsqueda","slug":"diseno-de-la-barra-de-busqueda","link":"#diseno-de-la-barra-de-busqueda","children":[]},{"level":3,"title":"Prioridad de tipos de resultado y activadores","slug":"prioridad-de-tipos-de-resultado-y-activadores","link":"#prioridad-de-tipos-de-resultado-y-activadores","children":[]}]},{"level":2,"title":"3. Ventana de búsqueda principal","slug":"_3-ventana-de-busqueda-principal","link":"#_3-ventana-de-busqueda-principal","children":[]},{"level":2,"title":"4. Ventana de vista previa","slug":"_4-ventana-de-vista-previa","link":"#_4-ventana-de-vista-previa","children":[]},{"level":2,"title":"5. Navegación rápida","slug":"_5-navegacion-rapida","link":"#_5-navegacion-rapida","children":[]},{"level":2,"title":"6. Vista previa y miniaturas","slug":"_6-vista-previa-y-miniaturas","link":"#_6-vista-previa-y-miniaturas","children":[]}],"relativePath":"es-ES/user-guide/settings/general.md","filePath":"es-ES/user-guide/settings/general.md","lastUpdated":1793171577000}`),a={name:`es-ES/user-guide/settings/general.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="configuracion-general" tabindex="-1">Configuración general <a class="header-anchor" href="#configuracion-general" aria-label="Permalink to “Configuración general”">​</a></h1><p>Configuración general abarca el comportamiento central del sistema, las dimensiones y el diseño visual de las ventanas de búsqueda, la ponderación de prioridad de los tipos de resultados y el orden de los proveedores de vista previa. La página se divide en seis pestañas superiores: <strong>Sistema</strong>, <strong>Ventana de búsqueda rápida</strong>, <strong>Ventana de búsqueda principal</strong>, <strong>Ventana de vista previa</strong>, <strong>Navegación rápida</strong> y <strong>Vista previa y miniaturas</strong>.</p><h2 id="_1-sistema" tabindex="-1">1. Sistema <a class="header-anchor" href="#_1-sistema" aria-label="Permalink to “1. Sistema”">​</a></h2><ul><li><strong>Iniciar Lertaro al arrancar el sistema</strong>: Inicia Lertaro automáticamente al iniciar sesión en Windows.</li><li><strong>Buscar actualizaciones al iniciar</strong>: Comprueba automáticamente en línea si hay nuevas versiones al abrir la aplicación.</li><li><strong>Actualizaciones silenciosas</strong>: Solo disponible cuando se ejecuta como administrador y &quot;Buscar actualizaciones&quot; está activo. Descarga e instala actualizaciones en segundo plano sin cuadros de diálogo molestos.</li><li><strong>Habilitar aceleración por hardware</strong>: Activado por defecto. Se aplica a las ventanas que mantienes abiertas (Ajustes, la ventana completa de búsqueda y la vista previa); las ventanas que invocas y cierras (búsqueda rápida, tarjeta en línea y notificaciones) se dibujan siempre por software, que es lo que hace que aparezcan ya pintadas en lugar de como un marco vacío. Si tu portátil con doble GPU (como NVIDIA Advanced Optimus) no cambia de gráfica por la presencia de Lertaro, desactívalo para renderizar todas las ventanas por software. Requiere reiniciar Lertaro.</li><li><strong>Ocultar icono de la bandeja del sistema</strong>: Oculta el icono del área de notificación. El logotipo dentro de la barra de búsqueda rápida sigue desplegando el menú completo de la bandeja.</li><li><strong>Habilitar servicio de compatibilidad Everything (IPC)</strong>: Emula el protocolo Win32 IPC de Everything para que Directory Opus, Total Commander y otras herramientas consulten el índice en memoria de Lertaro directamente.</li><li><strong>Habilitar coincidencia difusa</strong>: Activado por defecto. Permite coincidencias no consecutivas; si se desactiva, solo coincidirán subcadenas continuas (ver <a href="./../search-syntax.html"><strong>Sintaxis de búsqueda</strong></a>). Surte efecto inmediato.</li><li><strong>Mantener el contenido del cuadro de búsqueda al cerrar</strong>: Desactivado por defecto. Cuando está activo, ni ocultar la Ventana rápida ni pulsar <code>Escape</code> en la Ventana principal vacían el cuadro; <code>Escape</code> en la Ventana principal cierra la ventana a la primera pulsación en lugar de pedirlo dos veces. La consulta que recibe una ventana en su siguiente invocación llega <strong>seleccionada completa</strong>, así que la primera tecla la sustituye en lugar de añadirse. Esto solo dura la ejecución actual; el texto nunca se escribe en disco.</li><li><strong>Mostrar las carpetas abiertas actualmente en la búsqueda integrada</strong>: Cuando la ventana integrada está acoplada a un cuadro de diálogo de archivos, muestra las carpetas abiertas actualmente en ese diálogo cuando la consulta está vacía. Está activado de forma predeterminada.</li><li><strong>Ancho de la Ventana Integrada (%)</strong>: Cuadro de texto que acepta de <code>20</code> a <code>100</code>, por defecto <code>60</code>. La ventana integrada toma ese porcentaje del ancho de la ventana a la que se acopla. Guardar <code>60</code> no deja ninguna elección registrada, así que una tarjeta intacta toma el mayor entre el 40 % de esa ventana y una quinta parte del ancho de la pantalla. La pantalla sigue poniendo límites: nunca por debajo del mayor entre el 20 % de esa ventana y una sexta parte del ancho de la pantalla, y nunca por encima del menor entre esa ventana misma y el 90 % del ancho de la pantalla. Redúcelo si la tarjeta tapa demasiado una ventana maximizada.</li><li><strong>Filas de la Ventana Integrada (Ventana Normal)</strong>: Cuadro de texto que acepta de <code>4</code> a <code>10</code>, por defecto <code>10</code>. Cuántos resultados muestra la ventana integrada acoplada a una ventana normal. Los títulos de sección no cuentan: ocupan filas propias además del número que fijes. <code>Ctrl+1</code>–<code>Ctrl+9</code> seleccionan el primero al noveno resultado y <code>Ctrl+0</code> el décimo, de ahí el límite de 10. Si la pantalla no es lo bastante alta se muestran las filas que caben con desplazamiento.</li><li><strong>Filas de la Ventana Integrada (Selector de Archivos)</strong>: El mismo rango, por defecto <code>4</code>. Es el número de la tarjeta acoplada sobre un selector de archivos (Abrir/Guardar/Examinar); un selector es en gran parte controles de otro programa, así que esa tarjeta empieza más baja. Títulos, atajos y límite de pantalla funcionan igual que arriba.</li><li><strong>Delimitador de tokens de consulta</strong>: Campo de un solo carácter (por defecto <code>:</code>). Define el prefijo para los tokens de sufijo (p. ej. <code>:.pdf</code>, <code>:@doc</code>, <code>:[S]</code>).</li><li><strong>Nivel de registro</strong>: Selecciona Error / Advertencia / Información (predeterminado) / Depuración para la verbosidad de los registros.</li><li><strong>Idioma de la interfaz</strong>: Selecciona el idioma global de la aplicación.</li></ul><h2 id="_2-ventana-de-busqueda-rapida" tabindex="-1">2. Ventana de búsqueda rápida <a class="header-anchor" href="#_2-ventana-de-busqueda-rapida" aria-label="Permalink to “2. Ventana de búsqueda rápida”">​</a></h2><p>Permite ajustar con precisión las dimensiones geométricas y las prioridades de la barra flotante centrada:</p><h3 id="diseno-de-la-barra-de-busqueda" tabindex="-1">Diseño de la barra de búsqueda <a class="header-anchor" href="#diseno-de-la-barra-de-busqueda" aria-label="Permalink to “Diseño de la barra de búsqueda”">​</a></h3><ul><li><strong>Ancho de la barra (Píxeles)</strong>: Rango <code>300–1200px</code>, por defecto <code>570px</code>.</li><li><strong>Alto de la barra (Píxeles)</strong>: Rango <code>45–120px</code>, por defecto <code>60px</code>. Este valor escala proporcionalmente el tamaño de los iconos, el alto de fila y la tipografía para mantener la armonía visual.</li><li><strong>Mostrar reloj en la barra de búsqueda</strong>: Sustituye el texto de sugerencia por la fecha y hora actuales cuando la barra está vacía. Desaparece al empezar a escribir.</li><li><strong>Abrir ventana principal al pulsar de nuevo el atajo</strong>: Si la Ventana rápida ya está abierta, pulsar de nuevo su atajo transfiere la búsqueda activa a la Ventana principal.</li><li><strong>Bloquear posición</strong>: Evita que la barra se mueva accidentalmente al arrastrarla con el ratón.</li><li><strong>Rellenar automáticamente el texto del portapapeles</strong>: Desactivado por defecto. Cuando la Ventana de búsqueda rápida se abre sin texto preintroducido, usa como consulta el texto nuevo y no vacío del portapapeles. El pegado manual y las demás ventanas no se ven afectados.</li><li><strong>Recordar la última pestaña de la barra de filtros por tipo</strong>: Desactivado por defecto, así que al cerrar la ventana rápida la barra vuelve a <strong>Todo</strong>; al activarlo, la siguiente apertura se hace en la pestaña donde la dejaste. Solo dura la sesión actual: al reiniciar la aplicación la barra vuelve a «Todo».</li><li><strong>Restablecer diseño</strong>: Restaura todas las propiedades de diseño a sus valores predeterminados.</li></ul><h3 id="prioridad-de-tipos-de-resultado-y-activadores" tabindex="-1">Prioridad de tipos de resultado y activadores <a class="header-anchor" href="#prioridad-de-tipos-de-resultado-y-activadores" aria-label="Permalink to “Prioridad de tipos de resultado y activadores”">​</a></h3><ul><li><strong>Lista de ordenación de prioridades</strong>: Arrastra los controles para decidir qué tipos van primero <strong>entre coincidencias directas con relevancia similar</strong>, sin superar nunca a coincidencias directas exactas.</li><li><strong>Carácter activador exclusivo</strong>: Asigna un prefijo de un solo carácter (p. ej. <code>;</code> para Filtros de archivos) para aislar las búsquedas a ese tipo concreto.</li><li><strong>Exportación de detalles de ordenación</strong>: En la ventana rápida, haz clic derecho en cualquier resultado y elige <strong>Exportar los detalles de ordenación de esta página</strong> para escribir un archivo de texto de toda la página mostrada. El ajuste <strong>Permitir exportar los detalles de ordenación</strong> está activado por defecto.</li></ul><h2 id="_3-ventana-de-busqueda-principal" tabindex="-1">3. Ventana de búsqueda principal <a class="header-anchor" href="#_3-ventana-de-busqueda-principal" aria-label="Permalink to “3. Ventana de búsqueda principal”">​</a></h2><p>Configura las dimensiones predeterminadas y la vista de tabla para la ventana principal (<code>Ctrl+F</code>):</p><ul><li><strong>Ancho / Alto de la ventana (Píxeles)</strong>: Ancho <code>640–2000px</code> (por defecto <code>854px</code>), alto <code>400–1400px</code> (por defecto <code>480px</code>).</li><li><strong>Permitir solo una ventana principal</strong>: Al volver a abrir la ventana principal, enfoca la existente en lugar de duplicarla.</li><li><strong>Cerrar al repetir el atajo</strong>: Desactivado por defecto, pulsar de nuevo el atajo global con la ventana completa en primer plano vuelve a la ventana de búsqueda rápida manteniendo la consulta actual, alternando entre ambas ventanas hasta pulsar <code>Esc</code>. Si se activa, al pulsarlo de nuevo se cierra directamente la ventana completa. En ambos casos, si la ventana completa está visible pero sin foco, el atajo solo la trae de vuelta al frente.</li><li><strong>Restablecer configuración de ventana</strong>: Vuelve a los tamaños predeterminados de fábrica.</li><li><strong>Orden de columnas en la tabla</strong>: Personaliza el orden de las columnas (Nombre, Ruta, Fecha de modificación, etc.).</li><li><strong>Orden de filtros en la barra lateral</strong>: Reordena los filtros de la barra lateral; cada uno muestra en tiempo real el recuento de coincidencias activas.</li><li><strong>Orden de grupos del menú de acciones</strong>: Modifica la disposición de los grupos dentro del menú de acciones contextuales (<code>Ctrl+O</code>).</li></ul><h2 id="_4-ventana-de-vista-previa" tabindex="-1">4. Ventana de vista previa <a class="header-anchor" href="#_4-ventana-de-vista-previa" aria-label="Permalink to “4. Ventana de vista previa”">​</a></h2><ul><li><strong>Ancho / Alto de la vista previa (Píxeles)</strong>: Ancho <code>250–900px</code>, alto <code>250–1200px</code>.</li><li><strong>Restablecer vista previa</strong>: Devuelve el panel de QuickLook a sus proporciones estándar, manteniéndose siempre dentro de los límites visibles de la pantalla.</li></ul><h2 id="_5-navegacion-rapida" tabindex="-1">5. Navegación rápida <a class="header-anchor" href="#_5-navegacion-rapida" aria-label="Permalink to “5. Navegación rápida”">​</a></h2><ul><li><strong>Orden de proveedores</strong>: Reordena los grupos de proveedores del nivel superior en el menú de Navegación rápida. Cada fila es un proveedor, por ejemplo Cascada de Carpetas y Ejecutor de Comandos del Sistema, además de los grupos de marcadores de los complementos de exploradores.</li></ul><h2 id="_6-vista-previa-y-miniaturas" tabindex="-1">6. Vista previa y miniaturas <a class="header-anchor" href="#_6-vista-previa-y-miniaturas" aria-label="Permalink to “6. Vista previa y miniaturas”">​</a></h2><ul><li><strong>Orden de proveedores de vista previa</strong>: Ajusta la precedencia entre los renderizadores multimedia internos y el puente externo de QuickLook.</li><li><strong>Orden de proveedores de miniaturas</strong>: Ajusta la prioridad de los componentes encargados de extraer iconos y miniaturas de archivos.</li></ul>`,19)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};